$ErrorActionPreference='Stop'
$repo='D:\nips-temp\TotalP\P1\CRCICLR_PERSIST_INCREMENTAL_VALUE_V1';$exp=Join-Path $repo 'experiments\persist_eeg_pc_mechanism_closure_seed0_v1'
