$log=Join-Path $runtime 'scheduled_backtrace_checkpoint_EEGNet_OpenBMI_SSVEP_f4_v1.log';$python='E:\Anaconda\envs\persist_stable_251\python.exe'
$env:PERSIST_SOURCE_REPO=$repo;$env:MECHANISM_RUNTIME=$runtime;$env:COUPLING_RUNTIME='D:\nips-temp\TotalP\P1\protected_complement_coupling_runtime';$env:SEVEN_RUNTIME='D:\nips-temp\TotalP\P1\seven_backbone_fourtask_3seed_runtime';$env:OFFICIAL_BACKBONE_ROOT=Join-Path $env:SEVEN_RUNTIME 'official';$env:PYTHONUNBUFFERED='1'
function Log([string]$m){$m|Out-File $log -Append -Encoding utf8}
function Wait-Resources {while($true){$ram=(Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory/1MB;$raw=[string]((& nvidia-smi --query-gpu=memory.free --format=csv,noheader,nounits)|Select -First 1);$gpu=0;if(-not[int]::TryParse($raw.Trim(),[ref]$gpu)){throw 'GPU query failed'};$owned=@(Get-CimInstance Win32_Process|?{$_.Name-match'^python(\.exe)?$'-and$_.CommandLine-and$_.CommandLine-match'persist_eeg_pc_mechanism_closure_seed0_v1|pc_mechanism_closure_runtime'});if($ram-ge40-and$gpu-ge16000-and$owned.Count-eq0){return};Start-Sleep 20}}
function Invoke-Analysis([string]$arguments,[string]$phaseLog){Wait-Resources;$p=Join-Path $runtime $phaseLog;if(Test-Path $p){throw "phase log exists $phaseLog"};$cmd='"'+$python+'" -u '+$arguments+' >> "'+$p+'" 2>&1';& cmd.exe /d /c $cmd;if($LASTEXITCODE-ne0){throw "$phaseLog exited $LASTEXITCODE"}}
try {
  if(Test-Path $log){throw 'V1 log exists; refusing duplicate'};"BACKTRACE_CHECKPOINT_SSVEP_F4_V1_START utc=$([DateTime]::UtcNow.ToString('o'))"|Out-File $log -Encoding utf8
  if((Get-FileHash $back -Algorithm SHA256).Hash.ToLowerInvariant()-ne'ee8e79d274d439a6dab4505c70c9fbde0e13266fb5a86a034bf0580828f7539e'){throw 'backtrace source SHA mismatch'}
  if((Get-FileHash $mech -Algorithm SHA256).Hash.ToLowerInvariant()-ne'005685ec5c41871e2b002a319720ec5df1cf7e474cf5351b89d79e958daf9a0a'){throw 'mechanism source SHA mismatch'}
  if((Get-FileHash (Join-Path $exp 'protocol\MECHANISM_CLOSURE_ANALYSIS_LOCK.md') -Algorithm SHA256).Hash.ToLowerInvariant()-ne'ac12d33f7d30b2c846ec4c4fb07f8513bf25e372943a767b134883bf095a7c88'){throw 'lock SHA mismatch'}
  if((Get-FileHash (Join-Path $exp 'protocol\FINAL_PROJECTOR_AMENDMENT.md') -Algorithm SHA256).Hash.ToLowerInvariant()-ne'aec1e604d38f1901bd9eca7e072e30a3d496a28061a726ebbe63133259b0e474'){throw 'amendment SHA mismatch'}
  $gate=Get-Content (Join-Path $exp 'gate\GATE_AUDIT.json') -Raw|ConvertFrom-Json;if($gate.status-ne'PASSED'-or$gate.final_heldout_accessed-ne$false){throw 'gate invalid'}
  $up=Get-Content (Join-Path $env:COUPLING_RUNTIME 'cells\eegnet\openbmi_ssvep\fold4_seed0.json') -Raw|ConvertFrom-Json;if($up.status-ne'COMPLETE'-or$up.final_heldout_accessed-ne$false){throw 'Phase1 cell invalid'}
  $replayPath=Join-Path $cell 'replay_v2\REPLAY_AUDIT.json';$endpointPath=Join-Path $cell 'REPLICA_ENDPOINT_AUDIT_V1.json';$replay=Get-Content $replayPath -Raw|ConvertFrom-Json;$endpoint=Get-Content $endpointPath -Raw|ConvertFrom-Json
  if((Get-FileHash $replayPath -Algorithm SHA256).Hash.ToLowerInvariant()-ne'383d71b36e33f7ccccb0f7c6c6fce192484cccb9e73d7604d91d5561e603a561'-or(Get-FileHash $endpointPath -Algorithm SHA256).Hash.ToLowerInvariant()-ne'9d74d1a128e47ccc3cfbf261ab34449d72a409b35abe65ca1b6d3f178d599c28'){throw 'replay/endpoint SHA mismatch'}
  $epochs=@($endpoint.schedule|%{[int]$_.epoch}|Sort -Unique);if(($epochs-join',')-ne'6,15,30,41,45,60'-or$endpoint.final_heldout_accessed-ne$false){throw 'endpoint schedule invalid'}
  foreach($epoch in $epochs){$n=Get-Content (Join-Path $cell ("checkpoint_native_pt_v3\epoch_{0:000}.json"-f$epoch)) -Raw|ConvertFrom-Json;if($n.status-ne'NATIVE_CHECKPOINT_PT_COMPLETE_PENDING_BACKTRACE_AND_MECHANISM'-or[int]$n.fold-ne4-or$n.final_heldout_accessed-ne$false-or$n.outer_development_accessed-ne$false){throw "native invalid $epoch"}}
  $backResult=Join-Path $cell 'FINAL_P_BACKTRACE_V2.json';$backFail=Join-Path $cell 'FINAL_P_BACKTRACE_V2.FAIL_CLOSED.json';if(Test-Path $backFail){throw 'backtrace failed closed'};if(-not(Test-Path $backResult)){Invoke-Analysis ('"'+$back+'" --task OpenBMI_SSVEP --fold 4') 'scheduled_final_p_backtrace_EEGNet_OpenBMI_SSVEP_f4_v1.log'}
  $ba=Get-Content $backResult -Raw|ConvertFrom-Json;if($ba.status-ne'FINAL_P_BACKTRACE_COMPLETE_REPLICA_ONLY'-or[int]$ba.fold-ne4-or$ba.final_heldout_accessed-ne$false-or(@($ba.checkpoint_schedule_epochs)-join',')-ne($epochs-join',')){throw 'backtrace invalid'};Log "BACKTRACE_COMPLETE sha=$((Get-FileHash $backResult -Algorithm SHA256).Hash.ToLowerInvariant()) utc=$([DateTime]::UtcNow.ToString('o'))"
  foreach($epoch in $epochs){$tag='{0:000}'-f$epoch;$result=Join-Path $cell "checkpoint_mechanism_v2\epoch_$tag.json";$fail=Join-Path $cell "checkpoint_mechanism_v2\epoch_$tag.FAIL_CLOSED.json";if(Test-Path $fail){throw "mechanism failed closed $epoch"};if(-not(Test-Path $result)){Invoke-Analysis ('"'+$mech+'" --task OpenBMI_SSVEP --fold 4 --epoch '+$epoch) "scheduled_checkpoint_mechanism_EEGNet_OpenBMI_SSVEP_f4_v1_e${tag}.log"};$a=Get-Content $result -Raw|ConvertFrom-Json;if($a.status-ne'CHECKPOINT_MECHANISM_COMPLETE_REPLICA_ONLY'-or[int]$a.fold-ne4-or[int]$a.epoch-ne$epoch-or$a.final_heldout_accessed-ne$false-or$a.outer_development_accessed-ne$false){throw "mechanism invalid $epoch"};Log "MECHANISM_E${tag}_COMPLETE sha=$((Get-FileHash $result -Algorithm SHA256).Hash.ToLowerInvariant()) utc=$([DateTime]::UtcNow.ToString('o'))"}
  Log "BACKTRACE_CHECKPOINT_SSVEP_F4_V1_COMPLETE epochs=$($epochs-join',') utc=$([DateTime]::UtcNow.ToString('o'))";exit 0
}catch{if(Test-Path $log){Log "BACKTRACE_CHECKPOINT_SSVEP_F4_V1_EXCEPTION $($_.Exception.Message) utc=$([DateTime]::UtcNow.ToString('o'))"};exit 1}
